(() => {
const rows=[['Case diameter',-.0889274748,.0500803151,-.1145311133,.0115138949],['Case thickness',-.4049936033,1.3147132174e-20,-.313118142,1.6244054965e-12],['Band width',-.0846754981,.0621463679,.026184818,.5647049033],['Power reserve',-.0635807228,.1616721368,.2193644644,1.0441617527e-6],['Water resistance',-.1273756993,.0049191394,-.0919678177,.0427090994]];
const method=document.getElementById('watch-method'),order=document.getElementById('watch-order'),chart=document.getElementById('watch-bars'),detail=document.getElementById('watch-detail');
function render(){const col=method.value==='pearson'?1:3;const data=[...rows];if(order.value==='strength')data.sort((a,b)=>Math.abs(b[col])-Math.abs(a[col]));chart.replaceChildren();data.forEach(row=>{const b=document.createElement('button');b.type='button';b.className='watch-row';const label=document.createElement('span');label.textContent=row[0];const track=document.createElement('span');track.className='watch-track';const dot=document.createElement('i');dot.className='watch-dot';dot.style.left=((row[col]+1)*50)+'%';track.append(dot);const number=document.createElement('strong');number.textContent=row[col].toFixed(3);b.append(label,track,number);b.setAttribute('aria-label',row[0]+', '+method.value+' coefficient '+row[col].toFixed(3));const inspect=()=>{detail.textContent=row[0]+' · '+method.value+' coefficient: '+row[col].toFixed(3)+' · p-value: '+row[col+1].toExponential(3)+'. Saved notebook output; p-values do not measure effect size or establish causality. Multiple comparisons and cleaning choices require further checks.';};b.addEventListener('click',inspect);b.addEventListener('focus',inspect);chart.append(b);});detail.textContent='Select a feature to inspect the exact result. Scale: −1 on the left, 0 at the centre, +1 on the right. These are sample associations, not pricing rules.';}
method.addEventListener('change',render);order.addEventListener('change',render);render();
const captions={price:['assets/watch/price-distribution.png','Original notebook price histogram and box plot','Original notebook histogram and box plot. The long price tail makes medians, robust summaries and segment-specific comparisons useful next steps.'],brand:['assets/watch/brand-prices.png','Original notebook brand-level price comparison','Original notebook brand price comparison. Group composition and small samples can affect comparisons; this is not a ranking of brand demand or investment returns.']};document.querySelectorAll('[data-watch-figure]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-watch-figure]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const [src,alt,text]=captions[b.dataset.watchFigure];const image=document.getElementById('watch-figure');image.src=src;image.alt=alt;document.getElementById('watch-caption').textContent=text;}));
})();
